import 'package:flutter/material.dart'; import 'package:share_plus/share_plus.dart'; import '../../widgets/money.dart';
class CalculatorScreen extends StatefulWidget { const CalculatorScreen({super.key,required this.type,required this.title}); final String type,title; @override State<CalculatorScreen> createState()=>_CalculatorScreenState(); }
class _CalculatorScreenState extends State<CalculatorScreen>{ final fields=<String,TextEditingController>{}; double result=0,result2=0; String message=''; @override void initState(){super.initState(); for(final k in ['income','deduction','ctc','basic','hra','rent','salary','years','age','retire','increment','rate'])fields[k]=TextEditingController();}
 TextField input(String key,String label,{String? hint})=>TextField(controller:fields[key],keyboardType:TextInputType.number,decoration:InputDecoration(labelText:label,hintText:hint));
 void calculate(){ double n(String k)=>double.tryParse(fields[k]!.text)??0; setState((){message=''; if(widget.type=='tax'){final income=n('income'),ded=n('deduction'); final old=taxOld(income-ded), neu=taxNew(income-75000); result=old;result2=neu;message=old<neu?'Old Regime saves ${money(neu-old)}':'New Regime saves ${money(old-neu)}';} else if(widget.type=='salary'){final c=n('ctc'),basic=c*.4,pf=(basic*.12).clamp(0,1800*12);result=c-pf-2400;result2=result/12;message='Basic ${money(basic)} · PF ${money(pf)}';} else if(widget.type=='hra'){final b=n('basic'),h=n('hra'),r=n('rent'),cap=(r-b*.1),limit=b*.5;result=[h,cap,limit].reduce((a,b)=>a<b?a:b).clamp(0,double.infinity);result2=(h-result).clamp(0,double.infinity);message='Exempt: ${money(result)} · Taxable: ${money(result2)}';} else if(widget.type=='gratuity'){result=15*n('salary')*n('years')/26;message=n('years')<5?'Usually payable after 5 years of service.':'Eligible under the 5-year rule.';} else {final b=n('salary'),years=(n('retire')>0?n('retire'):58)-(n('age')); final rate=(n('rate')>0?n('rate'):8.25)/100; result=b*.12*12*((((1+rate)*((1+n('increment')/100)))-1)==0?years: (pow((1+rate)*((1+n('increment')/100)),years)-1)/(((1+rate)*((1+n('increment')/100)))-1));result2=years;message='Estimated corpus after ${years.toStringAsFixed(0)} years';}});}
 double pow(double a,double b){var v=1.0;for(var i=0;i<b;i++)v*=a;return v;} double taxOld(double x)=>x<=400000?0:x<=800000?(x-400000)*.05:x<=1200000?20000+(x-800000)*.1:x<=1600000?60000+(x-1200000)*.15:x<=2000000?120000+(x-1600000)*.2:x<=2400000?200000+(x-2000000)*.25:300000+(x-2400000)*.3; double taxNew(double x)=>x<=400000?0:x<=800000?(x-400000)*.05:x<=1200000?20000+(x-800000)*.1:x<=1600000?60000+(x-1200000)*.15:x<=2000000?120000+(x-1600000)*.2:x<=2400000?200000+(x-2000000)*.25:300000+(x-2400000)*.3;
 @override Widget build(BuildContext c){final keys=widget.type=='tax'?['income','deduction']:widget.type=='salary'?['ctc']:widget.type=='hra'?['basic','hra','rent']:widget.type=='gratuity'?['salary','years']:['salary','age','retire','increment','rate']; final labels={'income':'Annual income','deduction':'80C + 80D deductions','ctc':'Annual CTC','basic':'Monthly basic salary','hra':'Monthly HRA received','rent':'Monthly rent paid','salary':widget.type=='gratuity'?'Last drawn salary (basic + DA)':'Current basic salary','years':'Years of service','age':'Current age','retire':'Retirement age (default 58)','increment':'Annual increment % (default 5)','rate':'EPF interest % (default 8.25)'}; return Scaffold(appBar:AppBar(title:Text(widget.title)),body:ListView(padding:const EdgeInsets.all(16),children:[...keys.map((k)=>Padding(padding:const EdgeInsets.only(bottom:12),child:input(k,labels[k]!))),FilledButton.icon(onPressed:calculate,icon:const Icon(Icons.calculate),label:const Text('Calculate')),if(message.isNotEmpty)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Text('Result',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:8),MoneyText(result,style:const TextStyle(fontSize:28,fontWeight:FontWeight.bold)),if(result2>0)Text('Comparison / monthly: ${money(result2)}'),Text(message),Row(mainAxisAlignment:MainAxisAlignment.center,children:[TextButton.icon(onPressed:()=>Share.share('${widget.title}: ${money(result)}\n$message'),icon:const Icon(Icons.share),label:const Text('Share')),TextButton.icon(onPressed:()=>ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Result saved locally for this session'))),icon:const Icon(Icons.save),label:const Text('Save'))])])))]));}
}
